//! Component comparison of actual old and new gate calls, with a held owner.
//!
//! The baseline calls its original API and records what actually happens. API
//! absence is never treated as a failure. This fixture models a liveness flag;
//! it does not exercise Cx, SQLModel, request dispatch, or database operations.

use super::{SqliteInitGate, SqliteInitGateClaim, SqliteInitGateState, candidate};
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc;
use std::time::{Duration, Instant};

const WAIT_BUDGET: Duration = Duration::from_secs(5);
const CANCEL_OBSERVATION_WINDOW: Duration = Duration::from_millis(500);

#[derive(Clone)]
enum Gate {
    Baseline(Arc<SqliteInitGate>),
    Candidate(Arc<candidate::SqliteInitGate>),
}

#[derive(Debug, PartialEq, Eq)]
enum WaitOutcome {
    Initialize,
    Ready,
    TimedOut,
    Cancelled,
}

impl Gate {
    fn claim_owner(&self) {
        let outcome = self.wait(Duration::ZERO, &AtomicBool::new(false));
        assert_eq!(outcome, WaitOutcome::Initialize);
    }

    fn wait(&self, budget: Duration, cancelled: &AtomicBool) -> WaitOutcome {
        match self {
            // This is the exact old production API, not a stub or an adapter
            // that fabricates an unsupported cancellation outcome.
            Self::Baseline(gate) => match gate.claim_or_wait(budget) {
                SqliteInitGateClaim::Initialize => WaitOutcome::Initialize,
                SqliteInitGateClaim::Ready => WaitOutcome::Ready,
                SqliteInitGateClaim::TimedOut => WaitOutcome::TimedOut,
            },
            Self::Candidate(gate) => {
                let result = gate.claim_or_wait_with(budget, || {
                    if cancelled.load(Ordering::Acquire) {
                        Err(())
                    } else {
                        Ok(())
                    }
                });
                match result {
                    Ok(candidate::SqliteInitGateClaim::Initialize) => WaitOutcome::Initialize,
                    Ok(candidate::SqliteInitGateClaim::Ready) => WaitOutcome::Ready,
                    Ok(candidate::SqliteInitGateClaim::TimedOut) => WaitOutcome::TimedOut,
                    Err(()) => WaitOutcome::Cancelled,
                }
            }
        }
    }

    fn owner_retained(&self) -> bool {
        match self {
            Self::Baseline(gate) => {
                *gate.state.lock().unwrap() == SqliteInitGateState::Running
            }
            Self::Candidate(gate) => matches!(
                gate.claim_or_wait(Duration::ZERO),
                candidate::SqliteInitGateClaim::TimedOut
            ),
        }
    }

    fn complete(&self) {
        match self {
            Self::Baseline(gate) => gate.complete(true),
            Self::Candidate(gate) => gate.complete(true),
        }
    }
}

#[derive(Debug)]
struct Observation {
    waiter_started: bool,
    completed_before_cancellation: bool,
    completed_while_owner_held: bool,
    owner_retained_at_release: bool,
    outcome: WaitOutcome,
    owner_hold_after_cancel: Duration,
    completion_after_cancel: Duration,
}

fn observe(gate: Gate) -> Observation {
    gate.claim_owner();
    let cancelled = Arc::new(AtomicBool::new(false));
    let worker_gate = gate.clone();
    let worker_cancelled = Arc::clone(&cancelled);
    let (entered_tx, entered_rx) = mpsc::channel();
    let (done_tx, done_rx) = mpsc::channel();
    let worker = std::thread::spawn(move || {
        // The baseline has no waiter instrumentation. This handshake is
        // immediately before its actual gate call; the parent then gives the
        // waiting thread 50 ms before changing liveness. New production tests
        // separately witness an actual bounded wait interval in the candidate.
        entered_tx.send(()).unwrap();
        let outcome = worker_gate.wait(WAIT_BUDGET, &worker_cancelled);
        done_tx.send((outcome, Instant::now())).unwrap();
    });
    let waiter_started = entered_rx.recv_timeout(Duration::from_secs(2)).is_ok();
    let before_cancel = done_rx.recv_timeout(Duration::from_millis(50));
    let completed_before_cancellation = before_cancel.is_ok();
    let cancelled_at = Instant::now();
    cancelled.store(true, Ordering::Release);
    let during_hold = match before_cancel {
        Ok(result) => Some(result),
        Err(_) => done_rx.recv_timeout(CANCEL_OBSERVATION_WINDOW).ok(),
    };
    let completed_while_owner_held = during_hold.is_some();
    let owner_retained_at_release = gate.owner_retained();
    let owner_hold_after_cancel = cancelled_at.elapsed();
    // Every assertion follows owner release and worker join, including on a
    // regression, so the comparison never abandons a blocked waiter.
    gate.complete();
    let final_result = match during_hold {
        Some(result) => Some(result),
        None => done_rx.recv_timeout(WAIT_BUDGET).ok(),
    };
    let joined = worker.join();
    joined.expect("comparison waiter");
    let (outcome, completed_at) = final_result.expect("gate waiter eventually completes");
    Observation {
        waiter_started,
        completed_before_cancellation,
        completed_while_owner_held,
        owner_retained_at_release,
        outcome,
        owner_hold_after_cancel,
        completion_after_cancel: completed_at.saturating_duration_since(cancelled_at),
    }
}

#[test]
fn held_owner_cancellation_comparison() {
    let baseline = observe(Gate::Baseline(Arc::new(SqliteInitGate::new())));
    let candidate = observe(Gate::Candidate(Arc::new(candidate::SqliteInitGate::new())));
    eprintln!("BASELINE {baseline:?}");
    eprintln!("CANDIDATE {candidate:?}");
    assert!(baseline.waiter_started && candidate.waiter_started);
    assert!(!baseline.completed_before_cancellation);
    assert!(!candidate.completed_before_cancellation);
    assert!(baseline.owner_retained_at_release);
    assert!(candidate.owner_retained_at_release);
    assert!(!baseline.completed_while_owner_held);
    assert_eq!(baseline.outcome, WaitOutcome::Ready);
    assert!(baseline.owner_hold_after_cancel >= CANCEL_OBSERVATION_WINDOW);
    assert!(candidate.completed_while_owner_held);
    assert_eq!(candidate.outcome, WaitOutcome::Cancelled);
    assert!(candidate.completion_after_cancel < CANCEL_OBSERVATION_WINDOW);
}

