#![forbid(unsafe_code)]

// Exact production helper plus exact checked-layout tests. The additional Git
// CLI test exercises actual serialized indexes; it does not qualify git2 cache,
// scan-budget cancellation, publication, SQLite, or request-latency behavior.
use std::ops::Range;

struct EncodedPaths {
    next: Option<usize>,
}

impl EncodedPaths {
    fn new(encoded: &[u8]) -> Self {
        let version = encoded
            .get(4..8)
            .and_then(|bytes| <[u8; 4]>::try_from(bytes).ok())
            .map(u32::from_be_bytes);
        Self {
            next: matches!(version, Some(2 | 3)).then_some(12),
        }
    }

    fn take(&mut self, encoded: &[u8], expected: &[u8], oid_bytes: usize) -> Option<Range<usize>> {
        // Remove the cursor first. Any failed bound/equality check disables
        // subsequent ranges, instead of guessing where the next entry starts.
        let start = self.next.take()?;
        if !matches!(oid_bytes, 20 | 32) {
            return None;
        }
        let flags_start = start.checked_add(40)?.checked_add(oid_bytes)?;
        let flags_end = flags_start.checked_add(2)?;
        let flags = u16::from_be_bytes(encoded.get(flags_start..flags_end)?.try_into().ok()?);
        let path_start = flags_end.checked_add(if flags & 0x4000 == 0 { 0 } else { 2 })?;
        let path_end = path_start.checked_add(expected.len())?;
        if encoded.get(path_start..path_end)? != expected || *encoded.get(path_end)? != 0 {
            return None;
        }
        let used = path_end.checked_add(1)?.checked_sub(start)?;
        let padded = used.checked_add(7)? & !7;
        let next = start.checked_add(padded)?;
        // Padding belongs to this entry. It must be in bounds and zero; the
        // native decoder remains the authority for all following extensions.
        if encoded.get(path_end..next)?.iter().any(|byte| *byte != 0) {
            return None;
        }
        self.next = Some(next);
        Some(path_start..path_end)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Write;
    use std::path::Path;
    use std::process::{Command, Stdio};

    fn encoded_path_fixture(
        version: u32,
        oid_bytes: usize,
        extended: bool,
    ) -> (Vec<u8>, Vec<Vec<u8>>) {
        let names = [b"a".to_vec(), b"aligned/path".to_vec(), vec![b'x'; 4096]];
        let mut bytes = b"DIRC".to_vec();
        bytes.extend(version.to_be_bytes());
        bytes.extend(3_u32.to_be_bytes());
        for name in &names {
            let start = bytes.len();
            bytes.resize(start + 40 + oid_bytes, 0);
            bytes.extend(if extended { 0x4000_u16 } else { 0 }.to_be_bytes());
            if extended {
                bytes.extend(0x4000_u16.to_be_bytes());
            }
            bytes.extend(name);
            bytes.push(0);
            let size = (bytes.len() - start + 7) & !7;
            bytes.resize(start + size, 0);
        }
        (bytes, names.to_vec())
    }

    #[test]
    fn encoded_ranges_follow_padding_extensions_and_both_object_widths() {
        for version in [2, 3] {
            for oid_bytes in [20, 32] {
                for extended in [false, true] {
                    let (bytes, names) = encoded_path_fixture(version, oid_bytes, extended);
                    let mut paths = EncodedPaths::new(&bytes);
                    for name in &names {
                        let range = paths.take(&bytes, name, oid_bytes).unwrap();
                        assert_eq!(&bytes[range], name);
                    }
                    assert_eq!(paths.next, Some(bytes.len()));
                    assert!(paths.take(&bytes, b"unexpected", oid_bytes).is_none());
                    assert!(paths.next.is_none());
                }
            }
        }
    }

    #[test]
    fn unproved_encoded_ranges_disable_offsets_without_guessing() {
        let (bytes, names) = encoded_path_fixture(2, 20, false);
        for end in 0..12 + 64 {
            let truncated = &bytes[..end];
            let mut paths = EncodedPaths::new(truncated);
            assert!(paths.take(truncated, &names[0], 20).is_none());
            assert!(paths.next.is_none());
        }
        for invalid_width in [0, 19, 21, 31, 33, usize::MAX] {
            let mut paths = EncodedPaths::new(&bytes);
            assert!(paths.take(&bytes, &names[0], invalid_width).is_none());
            assert!(paths.next.is_none());
        }
        let mut mismatched = EncodedPaths::new(&bytes);
        assert!(mismatched.take(&bytes, b"b", 20).is_none());
        assert!(mismatched.take(&bytes, &names[0], 20).is_none());
        let mut corrupt = bytes.clone();
        corrupt[12 + 63] = 1; // First entry's terminating NUL/padding.
        let mut paths = EncodedPaths::new(&corrupt);
        assert!(paths.take(&corrupt, &names[0], 20).is_none());
        let mut overflow = EncodedPaths {
            next: Some(usize::MAX),
        };
        assert!(overflow.take(&bytes, &names[0], 20).is_none());
        for version in [0, 1, 4, u32::MAX] {
            let mut other = bytes.clone();
            other[4..8].copy_from_slice(&version.to_be_bytes());
            let mut paths = EncodedPaths::new(&other);
            assert!(paths.take(&other, &names[0], 20).is_none());
        }
    }

    #[test]
    fn helper_and_checked_layout_tests_are_exact_production_source() {
        let production = include_str!("/workspace/scratch/b1120803451c/gh353-continuation-7f188230/crates/mcp-agent-mail-storage/src/recovery/message_reconcile/identity/staged/decoded.rs");
        let harness = include_str!("encoded_paths.rs");
        let helper_start = production.find("struct EncodedPaths {").unwrap();
        let helper_end = production.find("\nstruct Decoded {").unwrap();
        assert!(harness.contains(&production[helper_start..helper_end]));
        let tests_start = production.find("    fn encoded_path_fixture(").unwrap();
        let tests_end = production
            .find("    #[test]\n    fn exact_bytes_reuse_decoding_and_preserve_native_prefix_verdicts")
            .unwrap();
        assert!(harness.contains(&production[tests_start..tests_end]));
    }

    fn git(directory: &Path, arguments: &[&str], input: Option<&[u8]>) -> Vec<u8> {
        let mut command = Command::new("git");
        command
            .current_dir(directory)
            .env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("LC_ALL", "C")
            .env("GIT_CONFIG_NOSYSTEM", "1")
            .env("GIT_CONFIG_GLOBAL", "/dev/null")
            .env("GIT_CONFIG_SYSTEM", "/dev/null")
            .args([
                "-c",
                "core.hooksPath=/dev/null",
                "-c",
                "gc.auto=0",
                "-c",
                "maintenance.auto=false",
            ])
            .args(arguments)
            .stdin(if input.is_some() { Stdio::piped() } else { Stdio::null() })
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        let mut child = command.spawn().unwrap();
        if let Some(input) = input {
            child.stdin.take().unwrap().write_all(input).unwrap();
        }
        let output = child.wait_with_output().unwrap();
        assert!(
            output.status.success(),
            "git {arguments:?}: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        output.stdout
    }

    #[test]
    fn actual_git_indexes_keep_v2_v3_names_and_decline_v4_ranges() {
        let root = std::env::var_os("GH353_INDEX_HELPER_FIXTURES")
            .expect("set GH353_INDEX_HELPER_FIXTURES to the retained task fixture directory");
        let root = Path::new(&root);
        std::fs::create_dir_all(root).unwrap();
        for format in ["sha1", "sha256"] {
            for version in [2_u32, 3, 4] {
                let dir = root.join(format!("{format}-v{version}-{}", std::process::id()));
                std::fs::create_dir(&dir).unwrap();
                git(
                    &dir,
                    &[
                        "init",
                        "--quiet",
                        "--template=",
                        "--initial-branch=main",
                        &format!("--object-format={format}"),
                        ".",
                    ],
                    None,
                );
                let oid = git(&dir, &["hash-object", "-w", "--stdin"], Some(b"real index fixture\n"));
                let oid = std::str::from_utf8(&oid).unwrap().trim();
                let width = oid.len() / 2;
                assert_eq!(width, if format == "sha1" { 20 } else { 32 });
                let long_name = format!("long/{}", "x".repeat(240));
                for name in ["Alpha", "alpha", "folder-neighbor/a", "folder/file", &long_name] {
                    git(
                        &dir,
                        &["update-index", "--add", "--cacheinfo", &format!("100644,{oid},{name}")],
                        None,
                    );
                }
                let mut conflicts = String::new();
                for stage in 1..=3 {
                    conflicts.push_str(&format!("100644 {oid} {stage}\tconflict/item\n"));
                }
                git(&dir, &["update-index", "--index-info"], Some(conflicts.as_bytes()));
                if version == 3 {
                    git(&dir, &["update-index", "--skip-worktree", "--", "alpha"], None);
                }
                git(&dir, &["update-index", &format!("--index-version={version}")], None);
                let listing = git(&dir, &["ls-files", "--stage", "-z"], None);
                let records: Vec<&[u8]> = listing.split(|byte| *byte == 0)
                    .filter(|record| !record.is_empty()).collect();
                let expected: Vec<&[u8]> = records.iter().map(|record| {
                    let tab = record.iter().position(|byte| *byte == b'\t').unwrap();
                    &record[tab + 1..]
                }).collect();
                assert_eq!(expected.iter().filter(|name| **name == b"conflict/item").count(), 3);
                let index_path = dir.join(".git/index");
                let bytes = std::fs::read(&index_path).unwrap();
                assert_eq!(&bytes[..4], b"DIRC");
                assert_eq!(u32::from_be_bytes(bytes[4..8].try_into().unwrap()), version);
                assert_eq!(u32::from_be_bytes(bytes[8..12].try_into().unwrap()) as usize, expected.len());
                let mut paths = EncodedPaths::new(&bytes);
                for name in &expected {
                    if version == 4 {
                        assert!(paths.take(&bytes, name, width).is_none());
                        assert!(paths.next.is_none());
                    } else {
                        let start = paths.next.unwrap();
                        let range = paths.take(&bytes, name, width).unwrap();
                        assert_eq!(&bytes[range], *name);
                        if version == 3 && *name == b"alpha" {
                            let flags_at = start + 40 + width;
                            let flags = u16::from_be_bytes(bytes[flags_at..flags_at + 2].try_into().unwrap());
                            let extended = u16::from_be_bytes(bytes[flags_at + 2..flags_at + 4].try_into().unwrap());
                            assert_ne!(flags & 0x4000, 0);
                            assert_ne!(extended & 0x4000, 0);
                        }
                    }
                }
                assert_eq!(std::fs::read(&index_path).unwrap(), bytes);
                println!("Git CLI fixture: {format} v{version}, {} native-listed entries, {} bytes, preserved index", expected.len(), bytes.len());
            }
        }
    }
}
